<?php if ($s->enabled('comments') && (int)$item['comment_enabled'] && $a->content->commentsVisible($me) && ($access || $item['access_level'] === 'reply')): ?><section class="comments panel glass" id="comments"><div class="section-heading"><h2><?= t('A conversation, not just a comment.') ?></h2><span class="pill"><?= (int)$commentFeed['total'] ?></span></div><?php if ($me): ?><?= form_start('comment',url($route,['id'=>$item['id'],'comment_sort'=>'latest']).'#comments','comment-form') . hidden('content_id',$item['id']) ?><?php field('body','Share a thought','','textarea',['required'=>'required','maxlength'=>'4000']); field('parent_id','Reply to comment ID (0 for a new comment)',0,'number',['min'=>'0']); button('Publish your reply','','message'); ?><p class="hint"><?= t('Comments may need moderation. Never publish passwords, payment keys or personal documents.') ?></p></form><?php else: ?><div class="alert info"><a href="<?= e(url('login')) ?>"><?= t('Sign in to join the conversation.') ?></a></div><?php endif ?><nav class="comment-filters filters" aria-label="<?= t('Comment order') ?>"><?php foreach(['latest'=>'Newest replies','oldest'=>'Oldest replies','author'=>'Only the author'] as $order=>$label): ?><a class="filter <?= $commentFeed['sort']===$order?'active':'' ?>" <?= $commentFeed['sort']===$order?'aria-current="true"':'' ?> href="<?= e(url($route,['id'=>(int)$item['id'],'comment_sort'=>$order])) ?>#comments"><?= t($label) ?></a><?php endforeach ?></nav><div class="comment-list"><?php foreach ($comments as $comment): ?><article class="comment<?= !empty($thread) && $thread['mode']==='question' && (int)$thread['accepted_comment_id']===(int)$comment['id'] ? ' answer-accepted' : '' ?>" id="comment-<?= (int)$comment['id'] ?>"><?= avatar($comment,'small') ?><div class="grow"><div class="comment-head"><strong><?= e($comment['display_name']) ?></strong><time><?= dt((int)$comment['created_at']) ?></time><span>#<?= (int)$comment['id'] ?><?= $comment['parent_id']?' / #'.(int)$comment['parent_id']:'' ?></span></div><p><?= nl2br(e($comment['body'])) ?></p><?php if(!empty($thread) && $thread['mode']==='question'): ?><?php if((int)$thread['accepted_comment_id']===(int)$comment['id']): ?><span class="pill accepted-answer"><?= icon('check') ?><?= t('Accepted answer') ?></span><?php elseif($me && !(int)$comment['parent_id'] && ((int)$me['id']===(int)$item['author_id'] || $a->auth->can('content'))): ?><?= form_start('answer_accept') . hidden('content_id',$item['id']) . hidden('comment_id',$comment['id']) ?><?php button('Accept this answer','ghost small','check'); ?></form><?php endif; endif ?><?php if($me): ?><button type="button" class="text-link reply-comment" data-reply-id="<?= (int)$comment['id'] ?>"><?= t('Reply') ?></button><?php endif ?><?php if((int)$comment['pinned']): ?><span class="pill"><?= t('Pinned') ?></span><?php endif ?><?php if($a->auth->can('moderate')): ?><?= form_start('admin_comment_pin') . hidden('id',$comment['id']) . hidden('pinned',(int)$comment['pinned']?0:1) ?><?php button((int)$comment['pinned']?'Unpin':'Pin to top','ghost small','pin'); ?></form><?php endif ?></div></article><?php endforeach ?><?php if (!$comments) {empty_state('Be the first to share a thought.','message');} ?></div><?php partial('pagination',['pagination'=>$commentFeed,'route'=>$route,'page_key'=>'comment_page','anchor'=>'comments']); ?></section><?php endif ?>
